    public static class Contractor
    {
        public static async Task<bool> IsAllowedForLeaveAsync(AppDbContext db, string userId)
        {
            var ptoCustIds = GetConfig("pto customers", "847", "App").Split(',').Select(int.Parse).ToArray();
            var query = from cp in db.ContractorPlacements
                        join p in db.Profiles on cp.Id equals p.ContractorPlacementId
                        where p.Id == cp.RecentProfileId && p.EmploymentTypeId == 4 && cp.ContractorId == userId && ptoCustIds.Contains(cp.CustomerId)
                        select cp.Id;
            return await query.AnyAsync();
        }

        public static async Task<bool> IsTsDirectAsync(AppDbContext db, string userId)
        {
            var query = from cp in db.ContractorPlacements
                        join p in db.Profiles on cp.RecentProfileId equals p.Id
                        where cp.ContractorId == userId && p.EmploymentTypeId != 1
                        orderby cp.Id descending
                        select cp.IsTsDirect;
            return await query.FirstOrDefaultAsync() == "Y";
        }

        public static async Task<bool> HasApproverAsync(AppDbContext db, int contractorId)
        {
            var query = from cp in db.ContractorPlacements
                        where cp.ContractorId == contractorId && cp.ApproverId != 1
                        select cp.ApproverId;
            return await query.AnyAsync();
        }

        public static async Task<string> NameByIdAsync(AppDbContext db, int contractorId)
        {
            var query = from c in db.Contractors
                        where c.Id == contractorId
                        select c.Name;
            return await query.FirstOrDefaultAsync();
        }
    }

