    // PortalContractorController.php L100-112 → getSum
    private static double GetSum(string arrayJson, string pattern) {
        var array = JsonSerializer.Deserialize<Dictionary<string, object>>(arrayJson);
        double sum = 0;
        foreach (var kvp in array) {
            var expKey = Regex.Split(kvp.Key, pattern);
            if (expKey.Length > 1 && !string.IsNullOrEmpty(expKey[1])) {
                if (double.TryParse(kvp.Value.ToString(), out var value)) {
                    sum += value;
                }
            }
        }
        return sum;
    }
